import{d as g,C as n,o as u,c as h,a3 as i,E as t,j as a,a as d}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"论语·微子","description":"《论语》第 18 篇「微子」——十一章原文与导读。殷有三仁、直道而事人、楚狂接舆、长沮桀溺、荷蓧丈人、逸民与「无可无不可」。","frontmatter":{"title":"论语·微子","description":"《论语》第 18 篇「微子」——十一章原文与导读。殷有三仁、直道而事人、楚狂接舆、长沮桀溺、荷蓧丈人、逸民与「无可无不可」。","category":"guide","aliases":["微子","微子篇","微子第十八","论语微子","lunyu 微子"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-18.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-18.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-18.md"},w=g({...p,setup(m){const r=[{id:"yi",label:"一、殷有三仁焉",showLabel:!0,sentences:[["微子去之，箕子为之奴，比干谏而死。孔子曰：“殷有三仁焉。”"]],note:"「微子去之，箕子为之奴，比干谏而死」——微子离去，箕子为奴（佯狂），比干谏而死。「孔子曰：殷有三仁焉」——殷有三仁。"},{id:"er",label:"二、直道而事人",showLabel:!0,sentences:[["柳下惠为士师，三",{text:"黜",glossary:"chu"},"。人曰：“子未可以去乎？”曰：“直道而事人，焉往而不三黜？枉道而事人，何必去父母之邦？”"]],note:"柳下惠为士师，三黜。人曰：「子未可以去乎」——您不可离去吗？曰：「直道而事人，焉往而不三黜？枉道而事人，何必去父母之邦」——以直道事人，往何处而不三黜？若以枉道事人，又何必离开父母之邦？"},{id:"san",label:"三、齐景公待孔子",showLabel:!0,sentences:[["齐景公待孔子曰：“若季氏，则吾不能。”以季、孟之间待之，曰：“吾老矣，不能用也。”孔子行。"]],note:"齐景公待孔子曰：「若季氏，则吾不能」——若如季氏那般，则我不能。「以季、孟之间待之」，曰：「吾老矣，不能用也」。孔子行。"},{id:"si",label:"四、齐人归女乐",showLabel:!0,sentences:[["齐人归女乐，季桓子受之，三日不朝，孔子行。"]],note:"齐人归（馈）女乐，季桓子受之，三日不朝。孔子行。"},{id:"wu",label:"五、楚狂接舆",showLabel:!0,sentences:[["楚狂接舆歌而过孔子曰：“凤兮凤兮，何德之衰？往者不可谏，来者犹可追。已而已而，今之从政者",{text:"殆",glossary:"dai-wei2"},"而！”孔子下，欲与之言，趋而",{text:"辟",glossary:"bi-bi3"},"之，不得与之言。"]],note:"楚狂接舆歌而过孔子曰：「凤兮凤兮，何德之衰？往者不可谏，来者犹可追。已而已而，今之从政者殆而」——凤啊凤啊，何德之衰？往者不可谏，来者犹可追；算了吧算了吧，今之从政者危矣！孔子下，欲与之言，趋而避之，不得与之言。"},{id:"liu",label:"六、长沮、桀溺耦而耕",showLabel:!0,sentences:[["长沮、桀溺",{text:"耦而耕",glossary:"ouergeng"},"，孔子过之，使子路问津焉。长沮曰：“夫执舆者为谁？”子路曰：“为孔丘。”曰：“是鲁孔丘与？”曰：“是也。”曰：“是知津矣。”问于桀溺，桀溺曰：“子为谁？”曰：“为仲由。”曰：“是鲁孔丘之徒与？”对曰：“然。”曰：“滔滔者天下皆是也，而谁以易之？且而与其从辟人之士也，岂若从辟世之士？”",{text:"耰而不辍",glossary:"youerbuchuo"},"。子路行以告，夫子",{text:"怃然",glossary:"wuran"},"曰：“鸟兽不可与同群，吾非斯人之徒与而谁与？天下有道，丘不与易也。”"]],note:"长沮、桀溺耦而耕。孔子过之，使子路问津焉。长沮曰：「夫执舆者为谁」？曰「为孔丘」。曰「是鲁孔丘与」？曰「是也」。曰：「是知津矣」。问于桀溺，曰：「子为谁」？曰「为仲由」。曰「是鲁孔丘之徒与」？曰「然」。桀溺曰：「滔滔者天下皆是也，而谁以易之？且而与其从辟人之士也，岂若从辟世之士哉」——天下滔滔皆是，谁能易之？且汝与其从避人之士，岂若从避世之士。耰而不辍。子路以告，夫子怃然曰：「鸟兽不可与同群，吾非斯人之徒与而谁与？天下有道，丘不与易也」——鸟兽不可与同群，我不与斯人同道又与谁？天下若有道，丘不与之易。"},{id:"qi",label:"七、子路从而后，遇丈人",showLabel:!0,sentences:[["子路从而后，遇丈人，以杖荷",{text:"蓧",glossary:"diao-nong"},"。子路问曰：“子见夫子乎？”丈人曰：“四体不勤，五谷不分，孰为夫子？”植其杖而芸，子路拱而立。止子路宿，杀鸡为黍而食之，见其二子焉。明日，子路行以告，子曰：“隐者也。”使子路反见之，至则行矣。子路曰：“不仕无义。长幼之节不可废也，君臣之义如之何其废之？欲洁其身而乱大伦。君子之仕也，行其义也，道之不行已知之矣。”"]],note:"子路从而后，遇丈人以杖荷蓧。子路问曰：「子见夫子乎」？丈人曰：「四体不勤，五谷不分，孰为夫子」？植其杖而芸。子路拱而立。止子路宿，杀鸡为黍而食之，见其二子焉。明日，子路行以告，子曰「隐者也」，使子路反见之，至则行矣。子路曰：「不仕无义。长幼之节，不可废也；君臣之义，如之何其废之？欲洁其身，而乱大伦。君子之仕也，行其义也。道之不行，已知之矣」。"},{id:"ba",label:"八、逸民：伯夷、叔齐",showLabel:!0,sentences:[["逸民：伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连。子曰：“不降其志，不辱其身，伯夷、叔齐与！”谓：“柳下惠、少连降志辱身矣，言中伦，行中虑，其斯而已矣。”谓：“虞仲、夷逸隐居放言，身中清，废中权。我则异于是，",{text:"无可无不可",glossary:"wukebukeweike"},"。”"]],note:"「逸民：伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连」。孔子评曰：「不降其志，不辱其身，伯夷、叔齐与」！谓：「柳下惠、少连降志辱身矣，言中伦，行中虑，其斯而已矣」；谓：「虞仲、夷逸隐居放言，身中清，废中权」。「我则异于是，无可无不可」——我与他们都不同：无可无不可。"},{id:"jiu",label:"九、太师挚适齐",showLabel:!0,sentences:[["太师挚适齐，亚饭干适楚，三饭缭适蔡，四饭缺适秦，鼓方叔入于河，播",{text:"鼗",glossary:"tao"},"武入于汉，少师阳、击磬襄入于海。"]],note:"「太师挚适齐，亚饭干适楚，三饭缭适蔡，四饭缺适秦，鼓方叔入于河，播鼗武入于汉，少师阳、击磬襄入于海」——鲁国乐官四散：太师挚去齐、亚饭干去楚、三饭缭去蔡、四饭缺去秦、鼓方叔入居河滨、播鼗武入居汉滨、少师阳与击磬襄入居海岛。见礼乐之崩坏。"},{id:"shi",label:"十、周公谓鲁公曰",showLabel:!0,sentences:[["周公谓鲁公曰：“君子不",{text:"施",glossary:"shi-chi"},"其亲，不使大臣怨乎不以，故旧无大故则不弃也，无求备于一人。”"]],note:"周公谓鲁公曰：「君子不施其亲（施＝弛、遗弃），不使大臣怨乎不以，故旧无大故则不弃也，无求备于一人」——君子不遗弃其亲族，不使大臣怨其不见用，故旧无大过则不弃，且不求全责备于一人。"},{id:"shiyi",label:"十一、周有八士",showLabel:!0,sentences:[["周有八士：伯达、伯适、仲突、仲忽、叔夜、叔夏、季随、季",{text:"騧",glossary:"gua"},"。"]],note:"「周有八士：伯达、伯适、仲突、仲忽、叔夜、叔夏、季随、季騧」——周有八士（八位贤士），记周初人才之盛。"}],o=[{id:"chu",term:"黜",pinyin:"chù",meaning:"罢免、贬退。三黜：三次被罢免。"},{id:"dai-wei2",term:"殆",pinyin:"dài",meaning:"危险。今之从政者殆而：如今从政的人危险啊。"},{id:"bi-bi3",term:"辟",pinyin:"bì",meaning:"同「避」。趋而辟之：快步避开他。"},{id:"ouergeng",term:"耦而耕",pinyin:"ǒu ér gēng",meaning:"两人并肩耕作。耦：两人并耕。"},{id:"youerbuchuo",term:"耰而不辍",pinyin:"yōu ér bù chuò",meaning:"耰：播种后用土覆盖、耙平；辍：停止。仍继续干活不停手（表示不愿再谈）。"},{id:"wuran",term:"怃然",pinyin:"wǔ rán",meaning:"怅然失意、心中不乐的样子。"},{id:"diao-nong",term:"蓧",pinyin:"diào",meaning:"除草用的竹器。以杖荷蓧：用拐杖挑着除草的工具。"},{id:"wukebukeweike",term:"无可无不可",pinyin:"wú kě wú bù kě",meaning:"没有什么一定可以，也没有什么一定不可以——依义而行，不预设立场。此为孔子自述与逸民之别。"},{id:"tao",term:"鼗",pinyin:"táo",meaning:"拨浪鼓（一种有柄的小鼓）。"},{id:"shi-chi",term:"施",pinyin:"shī",meaning:"同「弛」，疏远、怠慢（一说「施」为「遗弃」）。不施其亲：不怠慢自己的亲族。"},{id:"gua",term:"騧",pinyin:"guā",meaning:"黑嘴的黄马（此处为人名用字）。"}];return(c,e)=>{const s=n("DaoTextReading"),l=n("DaoKeywordCards");return u(),h("div",null,[e[0]||(e[0]=i("",6)),t(s,{colophon:"微子第十八 · 十一章",tone:"ink",sections:r,glossary:o,"default-mode":"slips","aria-label":"论语·微子 原文"}),e[1]||(e[1]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"黜",pinyin:["chù"],meaning:"罢免、贬退。三黜：三次被罢免。"},{term:"殆",pinyin:["dài"],meaning:"危险。今之从政者殆而：如今从政的人危险啊。"},{term:"辟",pinyin:["bì"],meaning:"同「避」。趋而辟之：快步避开他。"},{term:"耦而耕",pinyin:["ǒu","ér","gēng"],meaning:"两人并肩耕作。耦：两人并耕。"},{term:"耰而不辍",pinyin:["yōu","ér","bù","chuò"],meaning:"耰：播种后用土覆盖、耙平；辍：停止。仍继续干活不停手（表示不愿再谈）。"},{term:"怃然",pinyin:["wǔ","rán"],meaning:"怅然失意、心中不乐的样子。"},{term:"蓧",pinyin:["diào"],meaning:"除草用的竹器。以杖荷蓧：用拐杖挑着除草的工具。"},{term:"无可无不可",pinyin:["wú","kě","wú","bù","kě"],meaning:"没有什么一定可以，也没有什么一定不可以——依义而行，不预设立场。此为孔子自述与逸民之别。"},{term:"鼗",pinyin:["táo"],meaning:"拨浪鼓（一种有柄的小鼓）。"},{term:"施",pinyin:["shī"],meaning:"同「弛」，疏远、怠慢（一说「施」为「遗弃」）。不施其亲：不怠慢自己的亲族。"},{term:"騧",pinyin:["guā"],meaning:"黑嘴的黄马（此处为人名用字）。"}]}),e[2]||(e[2]=i("",26))])}}});export{y as __pageData,w as default};
